              <label><span>Datum event</span><input id="f-date" type="date"></label>
              <label><span>Postcode locatie</span><input id="f-pc" placeholder="1234 AB" autocomplete="postal-code"></label>
            </div>
            <label><span id="f-notes-label">Waar denk je aan?</span>
              <textarea id="f-notes" rows="3" placeholder="Bijvoorbeeld: personeelsfeest voor 120 man, statafels, glaswerk en een springkussen."></textarea>
            </label>
            <p class="msg" id="f-out" hidden></p>
            <div class="send">
              <small>We gebruiken je gegevens alleen voor deze aanvraag.</small>
              <button type="button" id="f-send">Aanvraag versturen</button>
            </div>
          </div>
        </div>

        <!-- stap 2: agenda (Calendly) -->
        <div id="step-cal" class="cal" hidden>
          <div class="cal-head">
            <div>
              <h3>Kies een moment</h3>
              <p>Joris — Dagpakketverhuur · 30 min · telefonisch of videocall</p>
            </div>
            <button type="button" id="cal-back">Terug</button>
          </div>
          <iframe id="cal-frame" title="Agenda kennismakingsgesprek" loading="lazy"></iframe>
          <div class="cal-note">Tijden komen uit de agenda van Joris — je krijgt de uitnodiging direct per mail.</div>
        </div>

        <!-- stap 3: bevestiging -->
        <div id="step-done" class="done" hidden>
          <b id="done-title">Aanvraag verstuurd</b>
          <p id="done-body">We nemen binnen één werkdag contact met je op met een vaste prijs. Spoed? Bel 085 212 9150.</p>
          <button type="button" id="done-again">Nog een aanvraag doen</button>
        </div>

      </div>
    </div>
  </section>

</div>
</template>

<script>
(function(){
  /* ── CALENDLY: plak hier de link naar het kennismakingsgesprek (30 min). ── */
  var CALENDLY = 'https://calendly.com/jorispieterkramer/30min';
  /* ─────────────────────────────────────────────────────────────────────── */

  var host=document.getElementById('dpv-zk-host'), tpl=document.getElementById('dpv-zk-tpl');
  if(!host||!tpl||host.dataset.init)return; host.dataset.init='1';

  if(!document.getElementById('dpv-zk-fonts')){
    var l=document.createElement('link'); l.id='dpv-zk-fonts'; l.rel='stylesheet';
    l.href='https://fonts.googleapis.com/css2?family=Poppins:wght@500;600&family=Inter:wght@400;500;600&display=swap';
    document.head.appendChild(l);
  }

  var root=host.attachShadow?host.attachShadow({mode:'open'}):host;
  root.appendChild(tpl.content.cloneNode(true));

  /* Lazy-load-plugins (LiteSpeed, WP Rocket, Perfmatters) vervangen src door
     data-src, maar hun JS komt niet in een shadow root — dan blijft het leeg.
     Daarom zetten we de bronnen hier zelf terug. */
  var herstel=function(scope){
    scope.querySelectorAll('img,source').forEach(function(el){
      var d=el.dataset||{};
      var src=d.src||d.lazySrc||d.original||d.lazyOriginal||el.getAttribute('data-lazy-src');
      if(src&&(!el.getAttribute('src')||/^data:image/.test(el.getAttribute('src'))))el.setAttribute('src',src);
      var ss=d.srcset||d.lazySrcset||el.getAttribute('data-lazy-srcset');
      if(ss&&!el.getAttribute('srcset'))el.setAttribute('srcset',ss);
      el.removeAttribute('loading');
      if(!el.dataset.dpvErr){
        el.dataset.dpvErr='1';
        el.addEventListener('error',function(){
          if(el.dataset.dpvRetry)return; el.dataset.dpvRetry='1';
          var s=el.getAttribute('src')||'';
          if(s)el.setAttribute('src',s+(s.indexOf('?')>-1?'&':'?')+'dpv=1');
        });
      }
    });
  };
  herstel(root);
  var $=function(id){return root.getElementById(id);};
  var qa=function(s){return [].slice.call(root.querySelectorAll(s));};

  /* logo-loop: één set, drie keer geplaatst (33.333% translate) */
  var LOGOS=[
    ['4fefb750-068f-4c9d-bfbe-3b2c1c1593ba','Klantlogo 1'],
    ['9b00e4ac-cd47-4e15-9f31-dc5663e4dffa','Klantlogo 2'],
    ['32c62e04-f07c-44be-b8aa-f8915ea66e55','Klantlogo 3'],
    ['72d0d779-5f10-44c5-882f-dfccb2323953','Klantlogo 4'],
    ['289035e5-76b6-44de-9fa1-59d9b5e9d371','Klantlogo 5'],
    ['dc3296c7-b2cb-4c14-9084-8d8d2283a460','Klantlogo 6'],
    ['e1c89a66-d7aa-4a1e-b782-dc4964d9357a','Klantlogo 7'],
    ['https://dagpakketverhuur.nl/wp-content/uploads/2026/09/dcterra_logo-vierkant_11zon.webp','Klantlogo DC Terra']
  ];
  var track=$('track'), html='';
  for(var r=0;r<3;r++)LOGOS.forEach(function(g){
    var src=g[0].indexOf('http')===0?g[0]:'https://dagpakketverhuur.nl/wp-content/uploads/2026/03/'+g[0]+'.png';
    html+='<img src="'+src+'" alt="'+g[1]+'">';
  });
  track.innerHTML=html;
  herstel(track);

  function api(){
    if(window.DPVS&&window.DPVS.ajax)return window.DPVS;
    return {ajax:location.origin+'/wp-admin/admin-ajax.php',nonce:''};
  }
  function post(action,data,done){
    var API=api(), body=new URLSearchParams();
    body.append('action',action); body.append('nonce',API.nonce);
    Object.keys(data).forEach(function(k){body.append(k,data[k]);});
    fetch(API.ajax,{method:'POST',credentials:'same-origin',body:body})
      .then(function(r){return r.text();})
      .then(function(t){
        var res=null; try{ res=JSON.parse(t); }catch(e){}
        if(res&&typeof res.success!=='undefined')return done(res);
        done({success:false,data:{message:'Versturen lukte niet (server gaf geen antwoord). Bel of WhatsApp ons op 085 212 9150.'}});
      })
      .catch(function(){done({success:false,data:{message:'Er ging iets mis. Probeer het opnieuw of bel 085 212 9150.'}});});
  }

  /* ── tabs ── */
  var type='aanvraag';
  var COPY={
    aanvraag:{title:'Vraag een zakelijke prijs aan',
      sub:'Vertel wat je nodig hebt; je krijgt binnen één werkdag een vaste prijs inclusief bezorgen en ophalen. Zakelijk betaal je op factuur, vóór de huurdatum.',
      notes:'Waar denk je aan?',
      ph:'Bijvoorbeeld: personeelsfeest voor 120 man, statafels, glaswerk en een springkussen.',
      btn:'Aanvraag versturen'},
    kennismaking:{title:'Plan een kennismakingsgesprek',
      sub:'Een half uur bellen of videobellen. Ik kijk met je mee wat je nodig hebt en of vaste afspraken voor jullie zin hebben.',
      notes:'Waar wil je het over hebben?',
      ph:'Bijvoorbeeld: we hebben drie vaste momenten per jaar en zoeken één partij die dat regelt.',
      btn: CALENDLY?'Naar de agenda':'Gesprek aanvragen'}
  };
  function step(which){
    $('step-form').hidden=which!=='form';
    $('step-cal').hidden=which!=='cal';
    $('step-done').hidden=which!=='done';
  }
  function setTab(t){
    type=t;
    qa('[data-tab]').forEach(function(b){b.setAttribute('aria-selected',b.dataset.tab===t?'true':'false');});
    qa('[data-only]').forEach(function(el){el.hidden=el.dataset.only!==t;});
    var c=COPY[t];
    $('f-title').textContent=c.title; $('f-sub').textContent=c.sub;
    $('f-notes-label').textContent=c.notes; $('f-notes').placeholder=c.ph;
    $('f-send').textContent=c.btn;
    $('f-out').hidden=true; step('form');
  }
  qa('[data-tab]').forEach(function(b){b.addEventListener('click',function(){setTab(b.dataset.tab);});});
  qa('[data-go]').forEach(function(b){b.addEventListener('click',function(){
    setTab(b.dataset.go);
    var y=host.getBoundingClientRect().top+window.pageYOffset;
    var sec=root.getElementById('zakelijk-aanvraag');
    window.scrollTo({top:y+sec.offsetTop-90,behavior:'smooth'});
  });});
  $('cal-back').addEventListener('click',function(){step('form');});
  $('done-again').addEventListener('click',function(){setTab(type);});
  setTab('aanvraag');

  /* ── versturen ── */
  var send=$('f-send'), out=$('f-out');
  function say(txt){ out.hidden=false; out.textContent=txt; }
  send.addEventListener('click',function(){
    var comp=$('f-comp').value.trim(), name=$('f-name').value.trim(),
        mail=$('f-mail').value.trim(), tel=$('f-tel').value.trim();
    if(!comp||!name||!mail||!tel){ say('Vul je bedrijfsnaam, contactpersoon, e-mailadres en telefoonnummer in.'); return; }
    out.hidden=true;
    var data={type:type,company:comp,contact:name,email:mail,phone:tel,
      sector:$('f-sector').value,notes:$('f-notes').value.trim()};
    if(type==='aanvraag'){ data.event_date=$('f-date').value; data.postcode=$('f-pc').value.trim(); }
    else{ data.volume=$('f-vol').value; data.mode=$('f-mode').value;
          data.moment=CALENDLY?'kiest zelf via de agenda':'terugbellen'; }
    send.disabled=true; var label=send.textContent; send.textContent='Versturen…';
    post('dpvs_business_request',data,function(res){
      send.disabled=false; send.textContent=label;
      var d=res&&res.data||{};
      if(!res||!res.success){ say(d.message||'Versturen lukte niet. Bel of WhatsApp ons op 085 212 9150.'); return; }
      if(type==='kennismaking'&&CALENDLY){
        var fr=$('cal-frame'), sep=CALENDLY.indexOf('?')>-1?'&':'?';
        if(!fr.src||fr.src==='about:blank')
          fr.src=CALENDLY+sep+'hide_gdpr_banner=1&name='+encodeURIComponent(name)+'&email='+encodeURIComponent(mail);
        step('cal');
      } else {
        $('done-title').textContent = type==='kennismaking' ? 'Gesprek aangevraagd' : 'Aanvraag verstuurd';
        $('done-body').textContent = type==='kennismaking'
          ? 'We bellen je binnen één werkdag om een moment af te spreken. Spoed? Bel 085 212 9150.'
          : 'We nemen binnen één werkdag contact met je op met een vaste prijs. Spoed? Bel 085 212 9150.';
        step('done');
      }
      ['f-comp','f-name','f-mail','f-tel','f-date','f-pc','f-notes'].forEach(function(id){var el=$(id); if(el)el.value='';});
    });
  });
})();
</script>
